import{_ as i,o as s,c as a,ae as t}from"./chunks/framework.EHGTsUvI.js";const k=JSON.parse('{"title":"Identity & Recovery","description":"","frontmatter":{},"headers":[],"relativePath":"guide/identity.md","filePath":"guide/identity.md"}'),n={name:"guide/identity.md"};function l(h,e,r,o,p,d){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="identity-recovery" tabindex="-1">Identity &amp; Recovery <a class="header-anchor" href="#identity-recovery" aria-label="Permalink to &quot;Identity &amp; Recovery&quot;">​</a></h1><h2 id="creating-an-identity" tabindex="-1">Creating an Identity <a class="header-anchor" href="#creating-an-identity" aria-label="Permalink to &quot;Creating an Identity&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Alice&quot;</span></span></code></pre></div><p>This generates:</p><ul><li>An <strong>Ed25519 keypair</strong> from a BIP-39 mnemonic (24 words, 256-bit entropy)</li><li>A <strong>Curve25519 keypair</strong> derived from the Ed25519 key (for key exchange)</li><li>A <strong>device name</strong> (defaults to your machine hostname)</li></ul><p>The private key is stored in your OS keystore:</p><ul><li><strong>Windows/macOS</strong>: Keytar (OS credential manager)</li><li><strong>Linux</strong>: Encrypted file with machine-derived AES-256-GCM key</li></ul><h2 id="recovery-phrase" tabindex="-1">Recovery Phrase <a class="header-anchor" href="#recovery-phrase" aria-label="Permalink to &quot;Recovery Phrase&quot;">​</a></h2><p>Your 24-word mnemonic is the <strong>only way</strong> to recover your identity. Palexplorer never stores it — it&#39;s shown once during setup.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> recover</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;word1 word2 word3 ... word24&quot;</span></span></code></pre></div><h2 id="handles" tabindex="-1">Handles <a class="header-anchor" href="#handles" aria-label="Permalink to &quot;Handles&quot;">​</a></h2><p>Handles are optional human-readable names (e.g., <code>@alice</code>) provided by the Discovery extension:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Register a handle</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> register</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Resolve a handle</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> whoami</span></span></code></pre></div><p>Registration uses challenge-response authentication with your Ed25519 key.</p><h2 id="guest-mode" tabindex="-1">Guest Mode <a class="header-anchor" href="#guest-mode" aria-label="Permalink to &quot;Guest Mode&quot;">​</a></h2><p>Guest login creates a temporary identity in memory — no keystore, no persistence:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">handl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Keys are wiped with <code>sodium_memzero()</code> on logout or exit.</p><h2 id="multi-device" tabindex="-1">Multi-Device <a class="header-anchor" href="#multi-device" aria-label="Permalink to &quot;Multi-Device&quot;">​</a></h2><p>Each device registers separately under the same handle. Devices are linked by the same Ed25519 public key:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> device</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> device</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rename</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Work Laptop&quot;</span></span></code></pre></div>`,21)])])}const g=i(n,[["render",l]]);export{k as __pageData,g as default};
